// Test_ScheduleAssociationProperty_STATUS_WhenPropertiesConverted_RoundTripsWithoutLoss tests if a specific instance of ScheduleAssociationProperty_STATUS can be assigned to storage and back losslessly
func Test_ScheduleAssociationProperty_STATUS_WhenPropertiesConverted_RoundTripsWithoutLoss(t *testing.T) {
	t.Parallel()

	if testing.Short() {
		return
	}

	rapid.Check(t, func(t *rapid.T) {
		subject := ScheduleAssociationProperty_STATUSGenerator().Draw(t, "subject")
		// Copy subject to make sure assignment doesn't modify it
		copied := subject.DeepCopy()

		// Use AssignPropertiesTo() for the first stage of conversion
		var other storage.ScheduleAssociationProperty_STATUS
		err := copied.AssignProperties_To_ScheduleAssociationProperty_STATUS(&other)
		if err != nil {
			t.Fatal("AssignPropertiesTo: " + err.Error())
		}

		// Use AssignPropertiesFrom() to convert back to our original type
		var actual ScheduleAssociationProperty_STATUS
		err = actual.AssignProperties_From_ScheduleAssociationProperty_STATUS(&other)
		if err != nil {
			t.Fatal("AssignPropertiesFrom: " + err.Error())
		}

		// Check for a match
		match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
		if !match {
			actualFmt := pretty.Sprint(actual)
			subjectFmt := pretty.Sprint(subject)
			result := diff.Diff(subjectFmt, actualFmt)
			t.Error(result)
		}
	})
}

func Test_ScheduleAssociationProperty_STATUS_WhenSerializedToJson_DeserializesAsEqual(t *testing.T) {
	t.Parallel()

	if testing.Short() {
		return
	}

	rapid.Check(t, RunJSONSerializationTestForScheduleAssociationProperty_STATUS)
}

// RunJSONSerializationTestForScheduleAssociationProperty_STATUS runs a test to see if a specific instance of ScheduleAssociationProperty_STATUS round trips to JSON and back losslessly
func RunJSONSerializationTestForScheduleAssociationProperty_STATUS(t *rapid.T) {
	subject := ScheduleAssociationProperty_STATUSGenerator().Draw(t, "subject")
	// Serialize to JSON
	bin, err := json.Marshal(subject)
	if err != nil {
		t.Fatal(err)
	}

	// Deserialize back into memory
	var actual ScheduleAssociationProperty_STATUS
	err = json.Unmarshal(bin, &actual)
	if err != nil {
		t.Fatal(err)
	}

	// Check for outcome
	match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
	if !match {
		actualFmt := pretty.Sprint(actual)
		subjectFmt := pretty.Sprint(subject)
		result := diff.Diff(subjectFmt, actualFmt)
		t.Error(result)
	}
}

